// kernel-audit-emitter — Phase 3 implementation
//
// REQ-XCT-002 / REQ-KER-018 / RC-5 / RC-12 / F-12
//
// Inputs (from previous node's $json):
//   event_type           : string (required) — e.g., 'agent.dispatch', 'stream.event_handled'
//   trace_id             : string (required) — inherited from upstream
//   stream_id            : string (required) — n8n workflow id ($workflow.id)
//   payload              : object (required) — event-specific payload (see schemas/events/audit-event.schema.json)
//
// Outputs (passed to next node):
//   { auditRow: { ... }, hmacSignature: '<hex>', endpoint: '<url>' }
//
// The HMAC token is read from $env.KERNEL_AUDIT_TOKEN. If missing, this
// node throws KER-AE-003 so the failure surfaces in the n8n execution
// rather than silently producing an unsigned row.

const crypto = require('crypto');

const inp = $input.first().json || {};
const event_type = inp.event_type;
const trace_id = inp.trace_id;
const stream_id = inp.stream_id || $workflow.id;
const userPayload = inp.payload || {};

if (!event_type) {
  throw new Error('KER-AE-002 missing required payload field: event_type');
}
if (!trace_id) {
  throw new Error('KER-AE-002 missing required payload field: trace_id');
}
if (!stream_id) {
  throw new Error('KER-AE-002 missing required payload field: stream_id (n8n workflow id)');
}

// F-12 parent_id composition: '<stream_id>:<n8n_node_id>'.
// n8n exposes the current node id via $node.id (the internal node identifier,
// stable across renames). $execution.id is the per-execution id and is also
// recorded so cross-execution traces resolve.
const node_id = ($node && $node.id) || ($node && $node.name) || 'unknown';
const parent_id = `${stream_id}:${node_id}`;

if (!parent_id.match(/^[A-Za-z0-9_-]+:[A-Za-z0-9_-]+$/)) {
  throw new Error(
    `KER-AE-002 parent_id failed F-12 pattern: ${parent_id} ` +
    `(must be '<stream_id>:<n8n_node_id>', both [A-Za-z0-9_-]+)`
  );
}

// Mutual exclusion check (RC-6 / F-04)
if (userPayload.prompt && userPayload.prompt_ref) {
  throw new Error('KER-AE-004 audit_payload_mixed_forms (prompt + prompt_ref)');
}
if (userPayload.response && userPayload.response_ref) {
  throw new Error('KER-AE-004 audit_payload_mixed_forms (response + response_ref)');
}

const timestamp = userPayload.timestamp || new Date().toISOString();

const auditRow = {
  event_type,
  trace_id,
  parent_id,
  timestamp,
  // Optional fields, only set when supplied to avoid schema 'null vs absent' confusion
  ...(userPayload.model_version !== undefined && { model_version: userPayload.model_version }),
  ...(userPayload.system_prompt_hash !== undefined && { system_prompt_hash: userPayload.system_prompt_hash }),
  ...(userPayload.prompt !== undefined && { prompt: userPayload.prompt }),
  ...(userPayload.prompt_ref !== undefined && { prompt_ref: userPayload.prompt_ref }),
  ...(userPayload.response !== undefined && { response: userPayload.response }),
  ...(userPayload.response_ref !== undefined && { response_ref: userPayload.response_ref }),
  ...(userPayload.tool_calls !== undefined && { tool_calls: userPayload.tool_calls }),
  ...(userPayload.cot !== undefined && { cot: userPayload.cot }),
  ...(userPayload.confidence !== undefined && { confidence: userPayload.confidence }),
  ...(userPayload.untrusted_regions !== undefined && { untrusted_regions: userPayload.untrusted_regions }),
  ...(userPayload.budget_echo !== undefined && { budget_echo: userPayload.budget_echo }),
  ...(userPayload.tokens_used !== undefined && { tokens_used: userPayload.tokens_used }),
  ...(userPayload.cost_usd !== undefined && { cost_usd: userPayload.cost_usd })
};

// RC-5: HMAC-SHA256 over canonical JSON, key = KERNEL_AUDIT_TOKEN.
// The governance-plugin write boundary recomputes this and rejects with
// AUDIT-001 unsigned_row if it does not match.
//
// NOTE: Ed25519 signing (per RC-5 'Ed25519 row-signed') is performed by the
// governance-plugin write boundary itself — it owns the kernel private key.
// The n8n emitter holds only the HMAC shared secret used to authenticate
// AS the kernel; governance-plugin then Ed25519-signs the row before commit.
// This separates emitter-authentication from row-integrity.
const token = $env.KERNEL_AUDIT_TOKEN || (typeof process !== 'undefined' && process.env && process.env.KERNEL_AUDIT_TOKEN);
if (!token) {
  throw new Error('KER-AE-003 audit_hmac_token_missing — set KERNEL_AUDIT_TOKEN env var on the n8n instance');
}

const canonical = JSON.stringify(auditRow, Object.keys(auditRow).sort());
const hmacSignature = crypto
  .createHmac('sha256', token)
  .update(canonical, 'utf8')
  .digest('hex');

const endpoint = $env.KERNEL_AUDIT_ENDPOINT || 'http://localhost:5681/audit/emit';

return [
  {
    json: {
      auditRow,
      hmacSignature,
      endpoint,
      // Surface useful metadata for downstream logging / debugging
      _meta: {
        n8n_execution_id: $execution.id,
        n8n_node_id: node_id,
        n8n_workflow_id: $workflow.id,
        canonical_bytes: canonical.length
      }
    }
  }
];
